6	// AscendC RotaryMul kernel
7	// All General Memory access uses GlobalTensor subscript base offset,
8	// never LocalTensor+offset (unsupported).
9	// Half mode: load 6 half-D slices from GM, compute, store 2 half-D slices.
10	// Interleave mode: 2-pass, each pass loads 6 quarter-D even/odd slices from GM
11	//   with stride-2 DataCopyPad, computes, stores to GM with stride-2 DataCopyPad.
12	
13	#include "kernel_operator.h"
14	
15	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
16	{
17	    return (b == 0U) ? 0U : (a + b - 1U) / b;
18	}
19	
20	template <typename T>
21	__aicore__ inline AscendC::RoundMode OutRound()
22	{
23	    if constexpr (std::is_same_v<T, bfloat16_t>) return AscendC::RoundMode::CAST_ROUND;
24	    return AscendC::RoundMode::CAST_NONE;
25	}
26	
27	template <typename dataType>
28	class RotaryMulKernel {
29	public:
30	    __aicore__ inline void Init(
31	        GM_ADDR xg, GM_ADDR r1g, GM_ADDR r2g, GM_ADDR yg,
32	        int32_t tr_, int32_t D_, int32_t hD_, int32_t bR_, int32_t uC_, int32_t tPC_,
33	        int64_t mF_)
34	    {
35	        totalRows = tr_; D = D_; halfD = hD_; blockRows = bR_;
36	        usedCoreNum = uC_; tasksPerCore = tPC_;
37	        isInterleave = (mF_ == 1);
38	
39	        uint64_t tot = static_cast<uint64_t>(tr_) * D_;
40	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(xg), tot);
41	        r1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(r1g), tot);
42	        r2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(r2g), tot);
43	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(yg), tot);
44	
45	        if ASCEND_IS_AIV {
46	            rowNum_ = CeilDivU32(static_cast<uint32_t>(tr_), static_cast<uint32_t>(bR_));
47	            tileH_ = static_cast<uint32_t>(bR_ * hD_);
48	            eSz_ = static_cast<uint32_t>(sizeof(dataType));
49	
50	            // 8 typed half-size buffers
51	            for (int i = 0; i < 8; ++i) {
52	                pipe_.InitBuffer(tBuf_[i], tileH_ * sizeof(dataType));
53	            }
54	            // 7 FP32 half-size buffers
55	            for (int i = 0; i < 7; ++i) {
56	                pipe_.InitBuffer(fBuf_[i], tileH_ * sizeof(float));
57	            }
58	        }
59	    }
60	
61	    __aicore__ inline void Process()
62	    {
63	        if ASCEND_IS_AIV {
64	            int cid = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
65	            for (int li = 0; li < tasksPerCore; ++li) {
66	                int bx = cid * tasksPerCore + li;
67	                if (bx >= static_cast<int>(rowNum_)) continue;
68	                int rs = bx * blockRows;
69	                int vr = totalRows - rs;
70	                if (vr > blockRows) vr = blockRows;
71	                if (vr <= 0) continue;
72	                uint32_t vH = static_cast<uint32_t>(vr * halfD);
73	                uint64_t go = static_cast<uint64_t>(rs) * D;
74	                uint64_t gh = go + vH;
75	                if (isInterleave) {
76	                    ProcessInterleave(go, vr, vH);
77	                } else {
78	                    ProcessHalf(go, gh, vH);
79	                }
80	            }
81	        }
82	    }
83	
84	private:
85	    // ----------------------------------------------------------------
86	    // GM↔UB
87	    // ----------------------------------------------------------------
88	    __aicore__ inline void Ld(AscendC::LocalTensor<dataType> &d,
89	                               AscendC::GlobalTensor<dataType> s, uint32_t c)
90	    {
91	        AscendC::DataCopyExtParams cp{1, c * eSz_, 0, 0, 0};
92	        AscendC::DataCopyPadExtParams<dataType> pp{true, 0, 0, static_cast<dataType>(0)};
93	        AscendC::DataCopyPad(d, s, cp, pp);
94	    }
95	    __aicore__ inline void St(AscendC::GlobalTensor<dataType> d,
96	                               AscendC::LocalTensor<dataType> &s, uint32_t c)
97	    {
98	        AscendC::DataCopyExtParams cp{1, c * eSz_, 0, 0, 0};
99	        AscendC::DataCopyPad(d, s, cp);
100	    }
101	
102	    // Strided: pick/write every `stride` elements
103	    __aicore__ inline void LdS(AscendC::LocalTensor<dataType> &d,
104	                                AscendC::GlobalTensor<dataType> s,
105	                                uint32_t nEl, uint32_t stride)
106	    {
107	        AscendC::DataCopyExtParams cp{static_cast<uint16_t>(nEl), eSz_, stride * eSz_, eSz_, 0};
108	        AscendC::DataCopyPadExtParams<dataType> pp{true, 0, 0, static_cast<dataType>(0)};
109	        AscendC::DataCopyPad(d, s, cp, pp);
110	    }
111	    __aicore__ inline void StS(AscendC::GlobalTensor<dataType> d,
112	                                AscendC::LocalTensor<dataType> &s,
113	                                uint32_t nEl, uint32_t stride)
114	    {
115	        AscendC::DataCopyExtParams cp{static_cast<uint16_t>(nEl), eSz_, eSz_, stride * eSz_, 0};
116	        AscendC::DataCopyPad(d, s, cp);
117	    }
118	
119	    // Cast
120	    __aicore__ inline void C2F(AscendC::LocalTensor<float> &d,
121	                                AscendC::LocalTensor<dataType> &s, uint32_t c)
122	    {
123	        if constexpr (std::is_same_v<dataType, float>) { d = s.template ReinterpretCast<float>(); }
124	        else { AscendC::Cast(d, s, AscendC::RoundMode::CAST_NONE, c); }
125	    }
126	    __aicore__ inline void F2C(AscendC::LocalTensor<dataType> &d,
127	                                AscendC::LocalTensor<float> &s, uint32_t c)
128	    {
129	        if constexpr (std::is_same_v<dataType, float>) { d = s.template ReinterpretCast<dataType>(); }
130	        else { AscendC::Cast(d, s, OutRound<dataType>(), c); }
131	    }
132	
133	    // ================================================================
134	    // Half mode
135	    // ================================================================
136	    __aicore__ inline void ProcessHalf(uint64_t go, uint64_t gh, uint32_t vH)
137	    {
138	        AscendC::LocalTensor<dataType> t[6];
139	        for (int i = 0; i < 6; ++i) t[i] = tBuf_[i].Get<dataType>();
140	        AscendC::LocalTensor<dataType> yt0 = tBuf_[6].Get<dataType>();
141	        AscendC::LocalTensor<dataType> yt1 = tBuf_[7].Get<dataType>();
142	
143	        // Load 6 half-D slices
144	        Ld(t[0], xGM_[go], vH);
145	        AscendC::PipeBarrier<PIPE_MTE2>();
146	        Ld(t[1], xGM_[gh], vH);
147	        AscendC::PipeBarrier<PIPE_MTE2>();
148	        Ld(t[2], r1GM_[go], vH);
149	        AscendC::PipeBarrier<PIPE_MTE2>();
150	        Ld(t[3], r1GM_[gh], vH);
151	        AscendC::PipeBarrier<PIPE_MTE2>();
152	        Ld(t[4], r2GM_[go], vH);
153	        AscendC::PipeBarrier<PIPE_MTE2>();
154	        Ld(t[5], r2GM_[gh], vH);
155	        AscendC::PipeBarrier<PIPE_ALL>();
156	
157	        // Cast to FP32
158	        AscendC::LocalTensor<float> f[7];
159	        for (int i = 0; i < 7; ++i) f[i] = fBuf_[i].Get<float>();
160	        C2F(f[0], t[0], vH);  // x0
161	        C2F(f[1], t[1], vH);  // x1
162	        C2F(f[2], t[2], vH);  // r10
163	        C2F(f[3], t[3], vH);  // r11
164	        C2F(f[4], t[4], vH);  // r20
165	        C2F(f[5], t[5], vH);  // r21
166	
167	        // y_first = x0*r10 - x1*r20 → store in f[0]
168	        AscendC::Mul(f[6], f[1], f[4], vH);   // tmp = x1 * r20
169	        AscendC::Mul(f[0], f[0], f[2], vH);   // f[0] = x0 * r10
170	        AscendC::Sub(f[0], f[0], f[6], vH);   // f[0] = y_first
171	
172	        // y_second = x1*r11 + x0*fresh*r21 → store in f[6]
173	        C2F(f[2], t[0], vH);                  // reload fresh x0
174	        AscendC::Mul(f[6], f[1], f[3], vH);   // tmp = x1 * r11
175	        AscendC::Mul(f[1], f[2], f[5], vH);   // x1_reused = x0_fresh * r21
176	        AscendC::Add(f[6], f[6], f[1], vH);   // f[6] = y_second
177	
178	        // Store
179	        F2C(yt0, f[0], vH);
180	        AscendC::PipeBarrier<PIPE_V>();
181	        St(yGM_[go], yt0, vH);
182	
183	        F2C(yt1, f[6], vH);
184	        AscendC::PipeBarrier<PIPE_V>();
185	        St(yGM_[gh], yt1, vH);
186	        AscendC::PipeBarrier<PIPE_MTE3>();
187	    }
188	
189	    // ================================================================
190	    // Interleave mode — 2 passes, one per half-D region
191	    // Pass 1: even/odd from first half (pos 0..hD-1)
192	    // Pass 2: even/odd from second half (pos hD..D-1)
193	    // Each pass: load 6 even/odd quarter-D slices via stride-2 DataCopyPad,
194	    // compute outEven/outOdd, store via stride-2 DataCopyPad.
195	    // ================================================================
196	    __aicore__ inline void ProcessInterleave(uint64_t go, int32_t vr, uint32_t vH)
197	    {
198	        uint32_t qH = vH / 2;  // quarter-D: hD/2 elements per half-region
199	
200	        // Run 2 passes
201	        for (int pass = 0; pass < 2; ++pass) {
202	            uint64_t base = (pass == 0) ? go : (go + vH);
203	            // Even positions in this region start at `base`
204	            // Odd positions start at `base + 1`
205	            uint64_t baseEven = base;
206	            uint64_t baseOdd  = base + 1;
207	
208	            // Get typed buffers
209	            AscendC::LocalTensor<dataType> t[6];
210	            for (int i = 0; i < 6; ++i) t[i] = tBuf_[i].Get<dataType>();
211	            AscendC::LocalTensor<dataType> ytEven = tBuf_[6].Get<dataType>();
212	            AscendC::LocalTensor<dataType> ytOdd  = tBuf_[7].Get<dataType>();
213	
214	            // --- Load even/odd slices ---
215	            LdS(t[0], xGM_[baseEven], qH, 2);        // xEven
216	            AscendC::PipeBarrier<PIPE_MTE2>();
217	            LdS(t[1], xGM_[baseOdd], qH, 2);         // xOdd
218	            AscendC::PipeBarrier<PIPE_MTE2>();
219	            LdS(t[2], r1GM_[baseEven], qH, 2);        // r1Even
220	            AscendC::PipeBarrier<PIPE_MTE2>();
221	            LdS(t[3], r1GM_[baseOdd], qH, 2);         // r1Odd
222	            AscendC::PipeBarrier<PIPE_MTE2>();
223	            LdS(t[4], r2GM_[baseEven], qH, 2);        // r2Even
224	            AscendC::PipeBarrier<PIPE_MTE2>();
225	            LdS(t[5], r2GM_[baseOdd], qH, 2);         // r2Odd
226	            AscendC::PipeBarrier<PIPE_ALL>();
227	
228	            // --- Cast to FP32 ---
229	            AscendC::LocalTensor<float> f[7];
230	            for (int i = 0; i < 7; ++i) f[i] = fBuf_[i].Get<float>();
231	            C2F(f[0], t[0], qH);  // xEven
232	            C2F(f[1], t[1], qH);  // xOdd
233	            C2F(f[2], t[2], qH);  // r1Even
234	            C2F(f[3], t[3], qH);  // r1Odd
235	            C2F(f[4], t[4], qH);  // r2Even
236	            C2F(f[5], t[5], qH);  // r2Odd
237	
238	            // --- Compute outEven = xEven*r1Even - xOdd*r2Even ---
239	            // f[6] = xOdd * r2Even
240	            AscendC::Mul(f[6], f[1], f[4], qH);
241	            // f[0] = xEven * r1Even
242	            AscendC::Mul(f[0], f[0], f[2], qH);
243	            // f[0] = outEven
244	            AscendC::Sub(f[0], f[0], f[6], qH);
245	
246	            // --- Compute outOdd = xOdd*r1Odd + xEven*r2Odd ---
247	            // We need fresh xEven. f[0] is now outEven, not xEven.
248	            // Reload xEven from typed buffer
249	            C2F(f[2], t[0], qH);  // f[2] = fresh xEven (reusing r1Even_f32 slot)
250	            // f[6] = xOdd * r1Odd
251	            AscendC::Mul(f[6], f[1], f[3], qH);
252	            // f[1] = xEven_fresh * r2Odd (reusing xOdd_f32 slot)
253	            AscendC::Mul(f[1], f[2], f[5], qH);
254	            // f[6] = outOdd
255	            AscendC::Add(f[6], f[6], f[1], qH);
256	
257	            // --- Cast back and store with stride-2 ---
258	            F2C(ytEven, f[0], qH);
259	            AscendC::PipeBarrier<PIPE_V>();
260	            StS(yGM_[baseEven], ytEven, qH, 2);
261	
262	            F2C(ytOdd, f[6], qH);
263	            AscendC::PipeBarrier<PIPE_V>();
264	            StS(yGM_[baseOdd], ytOdd, qH, 2);
265	            AscendC::PipeBarrier<PIPE_MTE3>();
266	        }
267	        (void)vr;
268	    }
269	
270	    // Members
271	    int32_t totalRows = 0, D = 0, halfD = 0, blockRows = 0;
272	    int32_t usedCoreNum = 0, tasksPerCore = 0;
273	    bool isInterleave = false;
274	    uint32_t rowNum_ = 0, tileH_ = 0, eSz_ = 0;
275	
276	    AscendC::TPipe pipe_;
277	    AscendC::GlobalTensor<dataType> xGM_, r1GM_, r2GM_, yGM_;
278	    AscendC::TBuf<AscendC::TPosition::VECCALC> tBuf_[8];
279	    AscendC::TBuf<AscendC::TPosition::VECCALC> fBuf_[7];
280	};
281	
282	// =========================================================================
283	extern "C" __global__ __aicore__ void rotary_mul(
284	    GM_ADDR xGM, GM_ADDR r1GM, GM_ADDR r2GM, GM_ADDR yGM,
285	    int32_t totalRows, int32_t D, int32_t halfD,
286	    int32_t blockRows, int32_t usedCoreNum, int32_t tasksPerCore,
287	    int64_t dtypeFlag, int64_t modeFlag)
288	{
289	    if (dtypeFlag == 0) {
290	        RotaryMulKernel<float> k;
291	        k.Init(xGM, r1GM, r2GM, yGM,
292	               totalRows, D, halfD, blockRows, usedCoreNum, tasksPerCore, modeFlag);
293	        k.Process();
294	    } else if (dtypeFlag == 1) {
295	        RotaryMulKernel<half> k;
296	        k.Init(xGM, r1GM, r2GM, yGM,
297	               totalRows, D, halfD, blockRows, usedCoreNum, tasksPerCore, modeFlag);
298	        k.Process();
299	    } else {
300	        RotaryMulKernel<bfloat16_t> k;
301	        k.Init(xGM, r1GM, r2GM, yGM,
302	               totalRows, D, halfD, blockRows, usedCoreNum, tasksPerCore, modeFlag);
303	        k.Process();
304	    }
305	}
