6	// RotaryMul op_host — tiling calculation + EXEC_KERNEL_CMD launch
7	
8	#include <algorithm>
9	#include <cstdint>
10	#include <string>
11	
12	#include <torch/extension.h>
13	#include <torch/library.h>
14	
15	#include "torch_kernel_helper.h"
16	#include "tiling/platform/platform_ascendc.h"
17	
18	#include "aclrtlaunch_rotary_mul.h"
19	
20	// ---------------------------------------------------------------------------
21	// Tiling constants
22	// ---------------------------------------------------------------------------
23	
24	constexpr int32_t DEFAULT_BLOCK_ROWS = 16;
25	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
26	
27	// ---------------------------------------------------------------------------
28	// Host function
29	// ---------------------------------------------------------------------------
30	
31	namespace ascend_kernel {
32	
33	at::Tensor rotary_mul(
34	    const at::Tensor &input,
35	    const at::Tensor &r1,
36	    const at::Tensor &r2,
37	    const std::string &rotary_mode)
38	{
39	    // Input validation
40	    TORCH_CHECK(input.dim() == 4, "input must be 4D [B, H, S, D]");
41	    TORCH_CHECK(r1.dim() == 4, "r1 must be 4D");
42	    TORCH_CHECK(r2.dim() == 4, "r2 must be 4D");
43	    TORCH_CHECK(
44	        input.scalar_type() == at::kFloat || input.scalar_type() == at::kHalf ||
45	            input.scalar_type() == at::kBFloat16,
46	        "input must be float16, float32, or bfloat16");
47	    TORCH_CHECK(r1.scalar_type() == input.scalar_type(),
48	        "r1 must have same dtype as input");
49	    TORCH_CHECK(r2.scalar_type() == input.scalar_type(),
50	        "r2 must have same dtype as input");
51	    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
52	    TORCH_CHECK(rotary_mode == "half" || rotary_mode == "interleave",
53	        "rotary_mode must be 'half' or 'interleave'");
54	
55	    // Shape calculations
56	    int32_t B = static_cast<int32_t>(input.sizes()[0]);
57	    int32_t H = static_cast<int32_t>(input.sizes()[1]);
58	    int32_t S = static_cast<int32_t>(input.sizes()[2]);
59	    int32_t D = static_cast<int32_t>(input.sizes()[3]);
60	    TORCH_CHECK(D % 2 == 0, "D must be even");
61	
62	    int32_t totalRows = B * H * S;
63	    int32_t halfD = D / 2;
64	
65	    // Broadcast r1, r2 if needed and ensure contiguous
66	    at::Tensor r1_bc = r1;
67	    at::Tensor r2_bc = r2;
68	    if (r1.sizes() != input.sizes()) {
69	        r1_bc = r1.expand({B, H, S, D}).contiguous();
70	    }
71	    if (r2.sizes() != input.sizes()) {
72	        r2_bc = r2.expand({B, H, S, D}).contiguous();
73	    }
74	
75	    // Create output tensor (same shape as input)
76	    at::Tensor output = at::empty_like(input);
77	
78	    // Tiling calculation
79	    int32_t rowNum = (totalRows + DEFAULT_BLOCK_ROWS - 1) / DEFAULT_BLOCK_ROWS;
80	    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, rowNum));
81	    int32_t tasksPerCore = (rowNum + usedCoreNum - 1) / usedCoreNum;
82	
83	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
84	    int64_t dtypeFlag = 0;
85	    if (input.scalar_type() == at::kHalf) {
86	        dtypeFlag = 1;
87	    } else if (input.scalar_type() == at::kBFloat16) {
88	        dtypeFlag = 2;
89	    }
90	
91	    // rotary_mode flag: 0=half, 1=interleave
92	    int64_t modeFlag = (rotary_mode == "interleave") ? 1 : 0;
93	
94	    // All tiling params as left values (required by EXEC_KERNEL_CMD)
95	    int32_t blockRows = DEFAULT_BLOCK_ROWS;
96	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
97	
98	    EXEC_KERNEL_CMD(rotary_mul, blockDim,
99	                    input, r1_bc, r2_bc, output,
100	                    totalRows, D, halfD, blockRows, usedCoreNum, tasksPerCore,
101	                    dtypeFlag, modeFlag);
102	
103	    return output;
104	}
