// AscendC HybridAttentionMaskPreparation kernel
// Pure Vector operator: generates two boolean attention masks from scalar
// parameters. Each core processes a block of T (target_length) rows,
// computing per-row comparison masks and writing to output positions.
//
// full_mask[i,j] = (source_idx[j] > i + past_kv) as uint8
// swa_mask[:] = 0 (all False per reference implementation)

#include "kernel_operator.h"

// ---------------------------------------------------------------------------
// ceil-div helper (AscendC does not support std::min/max)
// ---------------------------------------------------------------------------
__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    return (b == 0U) ? 0U : (a + b - 1U) / b;
}

__aicore__ inline int32_t MinI32(int32_t a, int32_t b)
{
    return (a < b) ? a : b;
}

// =========================================================================
// Kernel class — no dtype dispatch needed (output always uint8_t)
// =========================================================================
class KernelHybridMaskPrep {
public:
    __aicore__ inline void Init(
        GM_ADDR fmg, GM_ADDR smg,
        int32_t B_, int32_t Hf_, int32_t Hs_,
        int32_t Tsz_, int32_t Ssz_,
        int32_t pkv_, int32_t sw_,
        int32_t bT_, int32_t uC_, int32_t tPC_)
    {
        B        = B_;
        H_full   = Hf_;
        H_swa    = Hs_;
        T_size   = Tsz_;
        S_size   = Ssz_;
        pastKv   = pkv_;
        blockT   = bT_;
        usedCore = uC_;
        tasksPC  = tPC_;

        uint64_t fmsz = static_cast<uint64_t>(B_) * Hf_ * Tsz_ * Ssz_;
        uint64_t smsz = static_cast<uint64_t>(B_) * Hs_ * Tsz_ * Ssz_;
        fullGm_.SetGlobalBuffer(reinterpret_cast<__gm__ uint8_t *>(fmg), fmsz);
        swaGm_.SetGlobalBuffer(reinterpret_cast<__gm__ uint8_t *>(smg), smsz);

        if ASCEND_IS_AIV {
            // UB allocation: 4 buffers for mask generation
            //  srcBuf: int32_t[S] — arithmetic progression [0..S-1]
            //  cmpBuf: int32_t[S] — comparison result (all-1s / all-0s)
            //  outBuf: uint8_t[S] — cast result for output
            //  tmpBuf: uint8_t — temp for ArithProgression (~3*S*4 bytes)
            uint32_t sszU = static_cast<uint32_t>(Ssz_);
            uint32_t tmpNeeded = sszU * static_cast<uint32_t>(sizeof(int32_t)) * 3U;
            // Align tmpNeeded to 32B
            tmpNeeded = ((tmpNeeded + 31U) / 32U) * 32U;

            pipe_.InitBuffer(srcBuf_, sszU * sizeof(int32_t));
            pipe_.InitBuffer(cmpBuf_, sszU * sizeof(int32_t));
            pipe_.InitBuffer(outBuf_, sszU * sizeof(uint8_t));
            pipe_.InitBuffer(tmpBuf_, tmpNeeded);

            tileH_ = static_cast<uint32_t>(bT_ * Ssz_);
            eSz_   = static_cast<uint32_t>(sizeof(uint8_t));
        }

        rowNum_ = static_cast<int32_t>(CeilDivU32(
            static_cast<uint32_t>(Tsz_), static_cast<uint32_t>(bT_)));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t cid = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            for (int32_t li = 0; li < tasksPC; ++li) {
                int32_t bx = cid * tasksPC + li;
                if (bx >= rowNum_) continue;
                int32_t startRow = bx * blockT;
                int32_t endRow   = MinI32(startRow + blockT, T_size);
                if (endRow <= startRow) continue;

                // Get UB buffers
                AscendC::LocalTensor<int32_t> srcIdx = srcBuf_.Get<int32_t>();
                AscendC::LocalTensor<int32_t> cmpRes = cmpBuf_.Get<int32_t>();
                AscendC::LocalTensor<uint8_t> outRow = outBuf_.Get<uint8_t>();

                // Generate source index progression once per block
                // [0, 1, 2, ..., S_size-1] in int32_t
                {
                    AscendC::LocalTensor<uint8_t> tmp = tmpBuf_.Get<uint8_t>();
                    AscendC::ArithProgression(srcIdx, tmp,
                        int32_t(0), int32_t(1), S_size);
                }
                AscendC::PipeBarrier<PIPE_V>();

                // Process each row in this block
                for (int32_t ri = startRow; ri < endRow; ++ri) {
                    // -------------------------------------------------------
                    // FULL ATTENTION MASK
                    // -------------------------------------------------------
                    // Compare: cmpRes[j] = (srcIdx[j] > ri + pastKv) ? 0xFFFFFFFF : 0x00000000
                    int32_t threshold = ri + pastKv;
                    AscendC::Compare(cmpRes, srcIdx, threshold,
                        AscendC::CmpMode::GT,
                        static_cast<uint32_t>(S_size));

                    // Cast int32_t comparison mask to uint8_t
                    AscendC::Cast(outRow, cmpRes,
                        AscendC::RoundMode::CAST_NONE,
                        static_cast<uint32_t>(S_size));
                    AscendC::PipeBarrier<PIPE_V>();

                    // Write this row to all (B, H_full) positions
                    WriteRowToAllPositions(outRow, ri, true);

                    // -------------------------------------------------------
                    // SLIDING WINDOW ATTENTION MASK (all False)
                    // -------------------------------------------------------
                    AscendC::Duplicate(outRow, uint8_t(0),
                        static_cast<uint32_t>(S_size));
                    AscendC::PipeBarrier<PIPE_V>();

                    // Write zero row to all (B, H_swa) positions
                    WriteRowToAllPositions(outRow, ri, false);
                }
            }
        }
    }

private:
    // Write one row of mask to all (batch, head) positions for either
    // the full mask or the sliding window mask output.
    __aicore__ inline void WriteRowToAllPositions(
        AscendC::LocalTensor<uint8_t> &rowData,
        int32_t rowIdx,
        bool isFullMask)
    {
        int32_t numHeads = isFullMask ? H_full : H_swa;
        AscendC::GlobalTensor<uint8_t> &gmRef = isFullMask ? fullGm_ : swaGm_;

        uint32_t sU = static_cast<uint32_t>(S_size);
        AscendC::DataCopyExtParams cp{
            1U,
            sU * eSz_,
            0U,
            0U,
            0U,
        };

        for (int32_t b = 0; b < B; ++b) {
            for (int32_t h = 0; h < numHeads; ++h) {
                uint64_t offset = static_cast<uint64_t>(
                    ((b * numHeads + h) * T_size + rowIdx) * S_size);
                AscendC::DataCopyPad(
                    gmRef[offset],
                    rowData,
                    cp);
            }
        }
        AscendC::PipeBarrier<PIPE_MTE3>();
    }

    // Scalar parameters
    int32_t B = 0, H_full = 0, H_swa = 0;
    int32_t T_size = 0, S_size = 0;
    int32_t pastKv = 0;
