// HybridAttentionMaskPreparation op_host — tiling calculation + kernel launch
// This operator takes only scalar parameters and outputs two 4D bool tensors.

#include <algorithm>
#include <cstdint>
#include <vector>

#include <torch/extension.h>
#include <torch/library.h>
#include <torch/types.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_hybrid_attention_mask_preparation.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------
constexpr int32_t DEFAULT_BLOCK_T = 64;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------
namespace ascend_kernel {

std::vector<at::Tensor> hybrid_attention_mask_preparation(
    int64_t batch_size_scalar,
    int64_t seq_length_scalar,
    int64_t past_key_values_length_scalar,
    int64_t num_attention_heads,
    int64_t swa_num_attention_heads,
    int64_t sliding_window)
{
    int32_t B      = static_cast<int32_t>(batch_size_scalar);
    int32_t T      = static_cast<int32_t>(seq_length_scalar);
    int32_t pastKv = static_cast<int32_t>(past_key_values_length_scalar);
    int32_t H_full = static_cast<int32_t>(num_attention_heads);
    int32_t H_swa  = static_cast<int32_t>(swa_num_attention_heads);
    int32_t S      = T + pastKv;  // source_length

    // Input validation
    TORCH_CHECK(B > 0, "batch_size must be > 0");
    TORCH_CHECK(T > 0, "seq_length must be > 0");
    TORCH_CHECK(pastKv >= 0, "past_key_values_length must be >= 0");
    TORCH_CHECK(H_full > 0, "num_attention_heads must be > 0");
    TORCH_CHECK(H_swa > 0, "swa_num_attention_heads must be > 0");
    TORCH_CHECK(sliding_window >= 0, "sliding_window must be >= 0");

    // Allocate output tensors on NPU
    auto opts = at::TensorOptions()
        .dtype(at::kBool)
        .device(at::Device(c10::DeviceType::PrivateUse1));
    at::Tensor fullMask = at::empty({B, H_full, T, S}, opts);
    at::Tensor swaMask  = at::empty({B, H_swa, T, S}, opts);

    // Tiling calculation
    int32_t blockT = DEFAULT_BLOCK_T;
    int32_t numTBlocks = (T + blockT - 1) / blockT;
    int32_t usedCore = std::min<int32_t>(
        DEFAULT_NUM_PHYSICAL_CORES,
        std::max<int32_t>(1, numTBlocks));
    int32_t tasksPerCore = (numTBlocks + usedCore - 1) / usedCore;

    // All EXEC_KERNEL_CMD parameters must be lvalues
    uint32_t blockDim = static_cast<uint32_t>(usedCore);
    int32_t tasksPC_lv = tasksPerCore;

    EXEC_KERNEL_CMD(hybrid_attention_mask_preparation, blockDim,
                    fullMask, swaMask,
                    B, H_full, H_swa, T, S,
                    pastKv, static_cast<int32_t>(sliding_window),
                    blockT, static_cast<int32_t>(usedCore), tasksPC_lv);

    return {fullMask, swaMask};
}

}  // namespace ascend_kernel
