33	public:
34	    __aicore__ inline void Init(
35	        GM_ADDR fmg, GM_ADDR smg,
36	        int32_t B_, int32_t Hf_, int32_t Hs_,
37	        int32_t Tsz_, int32_t Ssz_,
38	        int32_t pkv_, int32_t sw_,
39	        int32_t bT_, int32_t uC_, int32_t tPC_)
40	    {
41	        B        = B_;
42	        H_full   = Hf_;
43	        H_swa    = Hs_;
44	        T_size   = Tsz_;
45	        S_size   = Ssz_;
46	        pastKv   = pkv_;
47	        blockT   = bT_;
48	        usedCore = uC_;
49	        tasksPC  = tPC_;
50	
51	        uint64_t fmsz = static_cast<uint64_t>(B_) * Hf_ * Tsz_ * Ssz_;
52	        uint64_t smsz = static_cast<uint64_t>(B_) * Hs_ * Tsz_ * Ssz_;
53	        fullGm_.SetGlobalBuffer(reinterpret_cast<__gm__ uint8_t *>(fmg), fmsz);
54	        swaGm_.SetGlobalBuffer(reinterpret_cast<__gm__ uint8_t *>(smg), smsz);
55	
56	        if ASCEND_IS_AIV {
57	            // UB allocation: 4 buffers for mask generation
58	            //  srcBuf: int32_t[S] — arithmetic progression [0..S-1]
59	            //  cmpBuf: int32_t[S] — comparison result (all-1s / all-0s)
60	            //  outBuf: uint8_t[S] — cast result for output
61	            //  tmpBuf: uint8_t — temp for ArithProgression (~3*S*4 bytes)
62	            uint32_t sszU = static_cast<uint32_t>(Ssz_);
63	            uint32_t tmpNeeded = sszU * static_cast<uint32_t>(sizeof(int32_t)) * 3U;
64	            // Align tmpNeeded to 32B
65	            tmpNeeded = ((tmpNeeded + 31U) / 32U) * 32U;
66	
67	            pipe_.InitBuffer(srcBuf_, sszU * sizeof(int32_t));
68	            pipe_.InitBuffer(cmpBuf_, sszU * sizeof(int32_t));
69	            pipe_.InitBuffer(outBuf_, sszU * sizeof(uint8_t));
70	            pipe_.InitBuffer(tmpBuf_, tmpNeeded);
71	
72	            tileH_ = static_cast<uint32_t>(bT_ * Ssz_);
73	            eSz_   = static_cast<uint32_t>(sizeof(uint8_t));
74	        }
75	
76	        rowNum_ = static_cast<int32_t>(CeilDivU32(
77	            static_cast<uint32_t>(Tsz_), static_cast<uint32_t>(bT_)));
78	    }
79	
80	    __aicore__ inline void Process()
81	    {
82	        if ASCEND_IS_AIV {
83	            int32_t cid = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
84	            for (int32_t li = 0; li < tasksPC; ++li) {
85	                int32_t bx = cid * tasksPC + li;
86	                if (bx >= rowNum_) continue;
87	                int32_t startRow = bx * blockT;
88	                int32_t endRow   = MinI32(startRow + blockT, T_size);
89	                if (endRow <= startRow) continue;
90	
91	                // Get UB buffers
92	                AscendC::LocalTensor<int32_t> srcIdx = srcBuf_.Get<int32_t>();
93	                AscendC::LocalTensor<int32_t> cmpRes = cmpBuf_.Get<int32_t>();
94	                AscendC::LocalTensor<uint8_t> outRow = outBuf_.Get<uint8_t>();
95	
96	                // Generate source index progression once per block
97	                // [0, 1, 2, ..., S_size-1] in int32_t
98	                {
99	                    AscendC::LocalTensor<uint8_t> tmp = tmpBuf_.Get<uint8_t>();
100	                    AscendC::ArithProgression(srcIdx, tmp,
101	                        int32_t(0), int32_t(1), S_size);
102	                }
103	                AscendC::PipeBarrier<PIPE_V>();
104	
105	                // Process each row in this block
106	                for (int32_t ri = startRow; ri < endRow; ++ri) {
107	                    // -------------------------------------------------------
108	                    // FULL ATTENTION MASK
109	                    // -------------------------------------------------------
110	                    // Compare: cmpRes[j] = (srcIdx[j] > ri + pastKv) ? 0xFFFFFFFF : 0x00000000
111	                    int32_t threshold = ri + pastKv;
112	                    AscendC::Compare(cmpRes, srcIdx, threshold,
113	                        AscendC::CmpMode::GT,
114	                        static_cast<uint32_t>(S_size));
115	
116	                    // Cast int32_t comparison mask to uint8_t
117	                    AscendC::Cast(outRow, cmpRes,
118	                        AscendC::RoundMode::CAST_NONE,
119	                        static_cast<uint32_t>(S_size));
120	                    AscendC::PipeBarrier<PIPE_V>();
121	
122	                    // Write this row to all (B, H_full) positions
123	                    WriteRowToAllPositions(outRow, ri, true);
124	
125	                    // -------------------------------------------------------
126	                    // SLIDING WINDOW ATTENTION MASK (all False)
127	                    // -------------------------------------------------------
128	                    AscendC::Duplicate(outRow, uint8_t(0),
129	                        static_cast<uint32_t>(S_size));
130	                    AscendC::PipeBarrier<PIPE_V>();
131	
132	                    // Write zero row to all (B, H_swa) positions
133	                    WriteRowToAllPositions(outRow, ri, false);
134	                }
135	            }
136	        }
137	    }
138	
139	private:
140	    // Write one row of mask to all (batch, head) positions for either
141	    // the full mask or the sliding window mask output.
142	    __aicore__ inline void WriteRowToAllPositions(
143	        AscendC::LocalTensor<uint8_t> &rowData,
144	        int32_t rowIdx,
145	        bool isFullMask)
146	    {
147	        int32_t numHeads = isFullMask ? H_full : H_swa;
148	        AscendC::GlobalTensor<uint8_t> &gmRef = isFullMask ? fullGm_ : swaGm_;
149	
150	        uint32_t sU = static_cast<uint32_t>(S_size);
151	        AscendC::DataCopyExtParams cp{
152	            1U,
153	            sU * eSz_,
154	            0U,
155	            0U,
156	            0U,
157	        };
158	
159	        for (int32_t b = 0; b < B; ++b) {
160	            for (int32_t h = 0; h < numHeads; ++h) {
161	                uint64_t offset = static_cast<uint64_t>(
162	                    ((b * numHeads + h) * T_size + rowIdx) * S_size);
163	                AscendC::DataCopyPad(
164	                    gmRef[offset],
165	                    rowData,
166	                    cp);
167	            }
168	        }
169	        AscendC::PipeBarrier<PIPE_MTE3>();
170	    }
171	
172	    // Scalar parameters
173	    int32_t B = 0, H_full = 0, H_swa = 0;
174	    int32_t T_size = 0, S_size = 0;
175	    int32_t pastKv = 0;
176	    int32_t blockT = 0, usedCore = 0, tasksPC = 0;
177	    int32_t rowNum_ = 0;
178	    uint32_t tileH_ = 0, eSz_ = 0;
