183	    AscendC::TBuf<AscendC::TPosition::VECCALC> cmpBuf_;
184	    AscendC::TBuf<AscendC::TPosition::VECCALC> outBuf_;
185	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
186	};
