6	// AscendC HybridAttentionMaskPreparation kernel
7	// Pure Vector operator: generates two boolean attention masks from scalar
8	// parameters. Uses int32_t internally (supported by all AscendC vector APIs),
9	// then host converts to bool.
10	//
11	// full_mask[i,j] = (source_idx[j] > i + past_kv) → int32 mask bit
12	// swa_mask[:] = 0 (all False per reference implementation)
13	
14	#include "kernel_operator.h"
15	
16	// ---------------------------------------------------------------------------
17	// ceil-div helper (AscendC does not support std::min/max)
18	// ---------------------------------------------------------------------------
19	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
20	{
21	    return (b == 0U) ? 0U : (a + b - 1U) / b;
22	}
23	
24	__aicore__ inline int32_t MinI32(int32_t a, int32_t b)
25	{
26	    return (a < b) ? a : b;
27	}
28	
29	// =========================================================================
30	// Kernel class — int32_t internal working type
31	// =========================================================================
32	class KernelHybridMaskPrep {
33	public:
34	    __aicore__ inline void Init(
35	        GM_ADDR fmg, GM_ADDR smg,
36	        int32_t B_, int32_t Hf_, int32_t Hs_,
37	        int32_t Tsz_, int32_t Ssz_,
38	        int32_t pkv_, int32_t sw_,
39	        int32_t bT_, int32_t uC_, int32_t tPC_)
40	    {
41	        B        = B_;
42	        H_full   = Hf_;
43	        H_swa    = Hs_;
44	        T_size   = Tsz_;
45	        S_size   = Ssz_;
46	        pastKv   = pkv_;
47	        blockT   = bT_;
48	        usedCore = uC_;
49	        tasksPC  = tPC_;
50	
51	        uint64_t fmsz = static_cast<uint64_t>(B_) * Hf_ * Tsz_ * Ssz_;
52	        uint64_t smsz = static_cast<uint64_t>(B_) * Hs_ * Tsz_ * Ssz_;
53	        fullGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(fmg), fmsz);
54	        swaGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(smg), smsz);
55	
56	        if ASCEND_IS_AIV {
57	            uint32_t sszU = static_cast<uint32_t>(Ssz_);
58	            uint32_t sszBytes = sszU * sizeof(int32_t);
59	
60	            // UB buffers — all int32_t
61	            //  srcBuf: arithmetic progression [0..S-1]
62	            //  cmpBuf: comparison result
63	            //  tmpBuf: temp for ArithProgression
64	            pipe_.InitBuffer(srcBuf_, sszBytes);
65	            pipe_.InitBuffer(cmpBuf_, sszBytes);
66	            pipe_.InitBuffer(tmpBuf_, sszBytes);
67	
68	            eSz_   = static_cast<uint32_t>(sizeof(int32_t));
69	        }
70	
71	        rowNum_ = static_cast<int32_t>(CeilDivU32(
72	            static_cast<uint32_t>(Tsz_), static_cast<uint32_t>(bT_)));
73	    }
74	
75	    __aicore__ inline void Process()
76	    {
77	        if ASCEND_IS_AIV {
78	            int32_t cid = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
79	            for (int32_t li = 0; li < tasksPC; ++li) {
80	                int32_t bx = cid * tasksPC + li;
81	                if (bx >= rowNum_) continue;
82	                int32_t startRow = bx * blockT;
83	                int32_t endRow   = MinI32(startRow + blockT, T_size);
84	                if (endRow <= startRow) continue;
85	
86	                // Get UB buffers — all int32_t
87	                AscendC::LocalTensor<int32_t> srcIdx = srcBuf_.Get<int32_t>();
88	                AscendC::LocalTensor<int32_t> cmpRes = cmpBuf_.Get<int32_t>();
89	                AscendC::LocalTensor<int32_t> tmpInt = tmpBuf_.Get<int32_t>();
90	
91	                // Generate source index progression once per block
92	                // [0, 1, 2, ..., S_size-1] in int32_t
93	                AscendC::ArithProgression(srcIdx, tmpInt,
94	                    int32_t(0), int32_t(1), S_size);
95	                AscendC::PipeBarrier<PIPE_V>();
96	
97	                uint32_t sU = static_cast<uint32_t>(S_size);
98	                AscendC::DataCopyExtParams cp{1U, sU * eSz_, 0U, 0U, 0U};
99	
100	                // Process each row in this block
101	                for (int32_t ri = startRow; ri < endRow; ++ri) {
102	                    // -------------------------------------------------------
103	                    // FULL ATTENTION MASK
104	                    // Compare: cmpRes = (srcIdx > ri + pastKv) as int32 mask
105	                    // -------------------------------------------------------
106	                    int32_t threshold = ri + pastKv;
107	                    AscendC::Compare(cmpRes, srcIdx, threshold,
108	                        AscendC::CmpMode::GT, sU);
109	                    AscendC::PipeBarrier<PIPE_V>();
110	
111	                    // Write cmpRes directly to all (B, H_full) positions
112	                    WriteRowToAllPositions(cmpRes, ri, true, cp);
113	
114	                    // -------------------------------------------------------
115	                    // SLIDING WINDOW ATTENTION MASK (all False)
116	                    // -------------------------------------------------------
117	                    AscendC::Duplicate(cmpRes, int32_t(0), sU);
118	                    AscendC::PipeBarrier<PIPE_V>();
119	
120	                    // Write zero row to all (B, H_swa) positions
121	                    WriteRowToAllPositions(cmpRes, ri, false, cp);
122	                }
123	            }
124	        }
125	    }
126	
127	private:
128	    // Write one row of mask to all (batch, head) positions
129	    __aicore__ inline void WriteRowToAllPositions(
130	        AscendC::LocalTensor<int32_t> &rowData,
131	        int32_t rowIdx,
132	        bool isFullMask,
133	        const AscendC::DataCopyExtParams &cp)
134	    {
135	        int32_t numHeads = isFullMask ? H_full : H_swa;
136	        AscendC::GlobalTensor<int32_t> &gmRef = isFullMask ? fullGm_ : swaGm_;
137	
138	        for (int32_t b = 0; b < B; ++b) {
139	            for (int32_t h = 0; h < numHeads; ++h) {
140	                uint64_t offset = static_cast<uint64_t>(
141	                    ((b * numHeads + h) * T_size + rowIdx) * S_size);
142	                AscendC::DataCopyPad(gmRef[offset], rowData, cp);
143	            }
144	        }
145	        AscendC::PipeBarrier<PIPE_MTE3>();
146	    }
147	
148	    // Scalar parameters
149	    int32_t B = 0, H_full = 0, H_swa = 0;
150	    int32_t T_size = 0, S_size = 0;
151	    int32_t pastKv = 0;
152	    int32_t blockT = 0, usedCore = 0, tasksPC = 0;
153	    int32_t rowNum_ = 0;
154	    uint32_t eSz_ = 0;
155	
156	    AscendC::TPipe pipe_;
157	    AscendC::GlobalTensor<int32_t> fullGm_, swaGm_;
158	    AscendC::TBuf<AscendC::TPosition::VECCALC> srcBuf_;
159	    AscendC::TBuf<AscendC::TPosition::VECCALC> cmpBuf_;
160	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
161	};
162	
163	// =========================================================================
164	extern "C" __global__ __aicore__ void hybrid_attention_mask_preparation(
165	    GM_ADDR fullMask, GM_ADDR swaMask,
166	    int32_t B, int32_t H_full, int32_t H_swa,
167	    int32_t T_size, int32_t S_size,
168	    int32_t past_kv, int32_t sliding_window,
169	    int32_t blockT, int32_t usedCore, int32_t tasksPC)
170	{
171	    KernelHybridMaskPrep k;
172	    k.Init(fullMask, swaMask,
173	        B, H_full, H_swa, T_size, S_size,
174	        past_kv, sliding_window,
175	        blockT, usedCore, tasksPC);
176	    k.Process();
177	}
