 * Licensed under the CANN Open Software License Agreement Version 2.0.
 */

// AscendC HybridAttentionMaskPreparation kernel
// Pure Vector operator: generates two boolean attention masks from scalar
// parameters. Uses int32_t internally, host converts to bool via .to(at::kBool).
//
// full_mask[i,j] = (source_idx[j] > i + past_kv) corresponds to mask=False
//   where causal condition (j <= i + past_kv) holds.
//
// Strategy: Compare (tensor-tensor, not tensor-scalar) to avoid scalar
// overload quirks. Threshold tensor is filled with (i + past_kv) via Duplicate.

#include "kernel_operator.h"

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    return (b == 0U) ? 0U : (a + b - 1U) / b;
}

__aicore__ inline int32_t MinI32(int32_t a, int32_t b)
{
    return (a < b) ? a : b;
}

class KernelHybridMaskPrep {
public:
    __aicore__ inline void Init(
        GM_ADDR fmg, GM_ADDR smg,
        int32_t B_, int32_t Hf_, int32_t Hs_,
        int32_t Tsz_, int32_t Ssz_,
        int32_t pkv_, int32_t sw_,
        int32_t bT_, int32_t uC_, int32_t tPC_)
    {
        B        = B_;
        H_full   = Hf_;
        H_swa    = Hs_;
        T_size   = Tsz_;
        S_size   = Ssz_;
        pastKv   = pkv_;
        blockT   = bT_;
        usedCore = uC_;
        tasksPC  = tPC_;

        uint64_t fmsz = static_cast<uint64_t>(B_) * Hf_ * Tsz_ * Ssz_;
        uint64_t smsz = static_cast<uint64_t>(B_) * Hs_ * Tsz_ * Ssz_;
        fullGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(fmg), fmsz);
        swaGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(smg), smsz);

        if ASCEND_IS_AIV {
            uint32_t sszU = static_cast<uint32_t>(Ssz_);
            uint32_t sszBytes = sszU * sizeof(int32_t);

            // 3 UB buffers:
            //  srcBuf: arithmetic progression [0..S-1]
            //  thrBuf: threshold values (filled per row)
            //  mskBuf: comparison result (mask)
            pipe_.InitBuffer(srcBuf_, sszBytes);
            pipe_.InitBuffer(thrBuf_, sszBytes);
            pipe_.InitBuffer(mskBuf_, sszBytes);

            eSz_ = static_cast<uint32_t>(sizeof(int32_t));
        }

        rowNum_ = static_cast<int32_t>(CeilDivU32(
            static_cast<uint32_t>(Tsz_), static_cast<uint32_t>(bT_)));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t cid = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            for (int32_t li = 0; li < tasksPC; ++li) {
                int32_t bx = cid * tasksPC + li;
                if (bx >= rowNum_) continue;
                int32_t startRow = bx * blockT;
                int32_t endRow   = MinI32(startRow + blockT, T_size);
                if (endRow <= startRow) continue;

                AscendC::LocalTensor<int32_t> srcIdx = srcBuf_.Get<int32_t>();
                AscendC::LocalTensor<int32_t> thrBuf = thrBuf_.Get<int32_t>();
                AscendC::LocalTensor<int32_t> mskBuf = mskBuf_.Get<int32_t>();

                // Generate [0, 1, ..., S_size-1] once per block
                AscendC::ArithProgression(srcIdx,
                    int32_t(0), int32_t(1), S_size);
                AscendC::PipeBarrier<PIPE_ALL>();

                uint32_t sU = static_cast<uint32_t>(S_size);
                AscendC::DataCopyExtParams cp{1U, sU * eSz_, 0U, 0U, 0U};

                for (int32_t ri = startRow; ri < endRow; ++ri) {
                    // --------------------------------------------------
                    // FULL ATTENTION MASK
                    // --------------------------------------------------
                    int32_t threshold = ri + pastKv;

                    // Fill threshold buffer
                    AscendC::Duplicate(thrBuf, threshold, sU);
                    AscendC::PipeBarrier<PIPE_V>();

                    // Tensor-tensor compare: mskBuf[j] = (srcIdx[j] > threshold)
                    AscendC::Compare(mskBuf, srcIdx, thrBuf,
                        AscendC::CMPMODE::GT, sU);
                    AscendC::PipeBarrier<PIPE_ALL>();

                    WriteRowToAllPositions(mskBuf, ri, true, cp);

                    // --------------------------------------------------
                    // SLIDING WINDOW ATTENTION MASK (all False → all 0)
                    // --------------------------------------------------
                    AscendC::Duplicate(mskBuf, int32_t(0), sU);
                    AscendC::PipeBarrier<PIPE_V>();

                    WriteRowToAllPositions(mskBuf, ri, false, cp);
                }
            }
        }
    }

private:
    __aicore__ inline void WriteRowToAllPositions(
        AscendC::LocalTensor<int32_t> &rowData,
        int32_t rowIdx,
        bool isFullMask,
        const AscendC::DataCopyExtParams &cp)
    {
        int32_t numHeads = isFullMask ? H_full : H_swa;
        AscendC::GlobalTensor<int32_t> &gmRef = isFullMask ? fullGm_ : swaGm_;

        for (int32_t b = 0; b < B; ++b) {
            for (int32_t h = 0; h < numHeads; ++h) {
