// Uses int32_t internally; host converts to bool via .to(at::kBool).
//
// Algorithm for each row i:
//   thrBuf = threshold (= i + past_kv_length)
//   diff   = threshold - srcIdx        (negated comparison)
//   sign   = diff >> 31                (arithmetic shift extracts sign)
//   result = sign                      (0xFFFFFFFF if srcIdx > threshold, 0 otherwise)

