                int32_t bx = cid * tasksPC + li;
                if (bx >= rowNum_) continue;
                int32_t startRow = bx * blockT;
                int32_t endRow   = MinI32(startRow + blockT, T_size);
                if (endRow <= startRow) continue;

                AscendC::LocalTensor<int32_t> srcIdx = srcBuf_.Get<int32_t>();
                AscendC::LocalTensor<int32_t> thrBuf = thrBuf_.Get<int32_t>();
                AscendC::LocalTensor<int32_t> outRow = outBuf_.Get<int32_t>();

                uint32_t sU = static_cast<uint32_t>(S_size);

                // Generate [0, 1, ..., S_size-1] once per block
                AscendC::ArithProgression(srcIdx,
                    int32_t(0), int32_t(1), S_size);
                AscendC::PipeBarrier<PIPE_ALL>();

                AscendC::DataCopyExtParams cp{1U, sU * eSz_, 0U, 0U, 0U};

                for (int32_t ri = startRow; ri < endRow; ++ri) {
                    // -------------------------------------------------------
                    // FULL ATTENTION MASK
                    // -------------------------------------------------------
                    int32_t threshold = ri + pastKv;

                    // thrBuf = threshold
                    AscendC::Duplicate(thrBuf, threshold, sU);
                    AscendC::PipeBarrier<PIPE_V>();

                    // thrBuf = threshold - srcIdx  (negated diff)
