{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * Licensed under the CANN Open Software License Agreement Version 2.0.
 */

// AscendC HybridAttentionMaskPreparation kernel
// Pure Vector operator. Generates full attention mask from scalar params.
// sliding_window_attention_mask is all-False per reference, handled by
// host-side at::zeros() initialization (no kernel writes needed).

#include "kernel_operator.h"

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    return (b == 0U) ? 0U : (a + b - 1U) / b;
}

__aicore__ inline int32_t MinI32(int32_t a, int32_t b)
{
    return (a < b) ? a : b;
}

class KernelHybridMaskPrep {
public:
    __aicore__ inline void Init(
        GM_ADDR fmg, GM_ADDR smg,
        int32_t B_, int32_t Hf_, int32_t Hs_,
        int32_t Tsz_, int32_t Ssz_,
        int32_t pkv_, int32_t sw_,
        int32_t bT_, int32_t uC_, int32_t tPC_)
    {
        B        = B_;
        H_full   = Hf_;
        H_swa    = Hs_;
        T_size   = Tsz_;
        S_size   = Ssz_;
        pastKv   = pkv_;
        blockT   = bT_;
        usedCore = uC_;
        tasksPC  = tPC_;

        uint64_t fmsz = static_cast<uint64_t>(B_) * Hf_ * Tsz_ * Ssz_;
        uint64_t smsz = static_cast<uint64_t>(B_) * Hs_ * Tsz_ * Ssz_;
        fullGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(fmg), fmsz);
        swaGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(smg), smsz);

        if ASCEND_IS_AIV {
            uint32_t sszU = static_cast<uint32_t>(Ssz_);
            uint32_t sszBytes = sszU * sizeof(int32_t);

            // 3 UB buffers (all full-size int32):
            //  srcBuf: [0..S-1] progression
            //  thrBuf: threshold / diff / sign result
            //  outBuf: temp for Sub output
            pipe_.InitBuffer(srcBuf_, sszBytes);
            pipe_.InitBuffer(thrBuf_, sszBytes);
            pipe_.InitBuffer(outBuf_, sszBytes);

            eSz_ = static_cast<uint32_t>(sizeof(int32_t));
        }

        rowNum_ = static_cast<int32_t>(CeilDivU32(
            static_cast<uint32_t>(Tsz_), static_cast<uint32_t>(bT_)));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t cid = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            for (int32_t li = 0; li < tasksPC; ++li) {
                int32_t bx = cid * tasksPC + li;
                if (bx >= rowNum_) continue;
                int32_t startRow = bx * blockT;
                int32_t endRow   = MinI32(startRow + blockT, T_size);
                if (endRow <= startRow) continue;

                AscendC::LocalTensor<int32_t> srcIdx = srcBuf_.Get<int32_t>();
                AscendC::LocalTensor<int32_t> thrBuf = thrBuf_.Get<int32_t>();
                AscendC::LocalTensor<int32_t> outRow = outBuf_.Get<int32_t>();

                uint32_t sU = static_cast<uint32_t>(S_size);
                AscendC::DataCopyExtParams cp{1U, sU * eSz_, 0U, 0U, 0U};

                // Generate [0, 1, ..., S_size-1] once per block
                AscendC::ArithProgression(srcIdx, int32_t(0), int32_t(1), S_size);
                AscendC::PipeBarrier<PIPE_ALL>();

                // Loop structure: for each (b, h) plane, process all rows.
                // This avoids interleaving DMA writes from different (b,h)
                // positions which can cause MTE queue issues on large tensors.
                for (int32_t b = 0; b < B; ++b) {
                    for (int32_t h = 0; h < H_full; ++h) {
                        uint64_t planeOff = static_cast<uint64_t>(
                            (b * H_full + h) * T_size) * S_size;

                        for (int32_t ri = startRow; ri < endRow; ++ri) {
                            AscendC::PipeBarrier<PIPE_ALL>();

                            int32_t threshold = ri + pastKv;

                            // thrBuf = threshold
                            AscendC::Duplicate(thrBuf, threshold, sU);
                            AscendC::PipeBarrier<PIPE_V>();

                            // outRow = threshold - srcIdx
                            AscendC::Sub(outRow, thrBuf, srcIdx, sU);
                            AscendC::PipeBarrier<PIPE_V>();

                            // thrBuf = sign(outRow) via arithmetic shift
                            // 0xFFFFFFFF when outRow<0 (srcIdx > threshold)
                            AscendC::ShiftRight(thrBuf, outRow, int32_t(31), sU);
                            AscendC::PipeBarrier<PIPE_V>();

                            // Write one row to one (b, h) position
                            uint64_t offset = planeOff +
                                static_cast<uint64_t>(ri) * S_size;
                            AscendC::DataCopyPad(fullGm_[offset], thrBuf, cp);
                        }
                        // Full sync after all rows for this (b,h) plane
                        AscendC::PipeBarrier<PIPE_ALL>();
                    }
                }
            }
        }
    }

private:
    int32_t B = 0, H_full = 0, H_swa = 0;
    int32_t T_size = 0, S_size = 0;
    int32_t pastKv = 0;
    int32_t blockT = 0, usedCore = 0, tasksPC = 0;
    int32_t rowNum_ = 0;
    uint32_t eSz_ = 0;

    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<int32_t> fullGm_, swaGm_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> srcBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> thrBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outBuf_;
};

extern "C" __global__ __aicore__ void hybrid_attention_mask_preparation(
    GM_ADDR fullMask, GM_ADDR swaMask,
    int32_t B, int32_t H_full, int32_t H_swa,
    int32_t T_size, int32_t S_size,
    int32_t past_kv, int32_t sliding_window,
    int32_t blockT, int32_t usedCore, int32_t tasksPC)
{
    KernelHybridMaskPrep k;
    k.Init(fullMask, swaMask,
        B, H_full, H_swa, T_size, S_size,
        past_kv, sliding_window,
        blockT, usedCore, tasksPC);
    k.Process();
}
